/**
 * Typed client + TanStack Query hooks for /api/v1/scoping (Hypothesis Chat).
 *
 * Every type here is an alias into `openapi.gen.ts`, which is generated by
 * `npm run types:generate` against the live BACKEND-API schema. Nothing in this
 * file hand-writes a response shape: if the API changes and the types are
 * regenerated, this stops compiling, which is the point.
 *
 * ADR-012, commitment 1: the server owns the config. There is no local form
 * object here. One answer goes out at a time and the server says what to ask
 * next.
 */

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { api } from './client'
import type { components } from './openapi.gen'

// ── Types (generated, not authored) ──────────────────────────────────────────

export type SessionState = components['schemas']['SessionStateResponse']
export type Question = components['schemas']['QuestionOut']
export type Prefill = components['schemas']['PrefillOut']
export type ExtractResult = components['schemas']['ExtractResponse']
export type CapabilityGap = components['schemas']['CapabilityGapOut']
export type Brief = components['schemas']['BriefResponse']
export type Review = components['schemas']['ReviewResponse']
export type Concern = components['schemas']['ConcernOut']
export type DispatchResult = components['schemas']['DispatchResponse']

/** Slot types the tree may declare. Mirrors `SlotType` in app/scoping/schema.py. */
export type SlotType =
  | 'text'
  | 'enum'
  | 'multi_select'
  | 'integer'
  | 'float'
  | 'filter'
  | 'object'

const ROOT = '/api/v1/scoping'

// ── options_from ─────────────────────────────────────────────────────────────
//
// Exactly three forms, per app/scoping/schema.py OPTIONS_SOURCE_FORMS. Nothing
// downstream may hardcode a domain value: options are resolved from the live
// catalog or from the API's own JSON Schema at ask-time.

export type OptionsSource =
  | { kind: 'literal'; values: string[] }
  | { kind: 'endpoint'; path: string }
  | { kind: 'schema'; name: string }

export function parseOptionsFrom(spec: string | null | undefined): OptionsSource | null {
  if (!spec) return null
  if (spec.startsWith('literal:')) {
    return { kind: 'literal', values: spec.slice('literal:'.length).split(',').filter(Boolean) }
  }
  if (spec.startsWith('endpoint:')) {
    return { kind: 'endpoint', path: spec.slice('endpoint:'.length) }
  }
  if (spec.startsWith('schema:')) {
    return { kind: 'schema', name: spec.slice('schema:'.length) }
  }
  return null
}

/** One selectable option resolved from an `endpoint:` source. */
export interface EndpointOption {
  /** Stable identity for selection state. */
  id: string
  label: string
  description?: string
  /** Optional grouping key, used for headings when the payload carries one. */
  group?: string
  /** The value posted as (part of) the answer. */
  value: unknown
}

/**
 * Project one catalog item onto an answerable value.
 *
 * Deliberately structural, never domain-specific: it reads generic key names
 * that the payload itself carries. No feature name, dataset name or column name
 * appears in this file.
 */
function toEndpointOption(item: Record<string, unknown>): EndpointOption {
  const str = (k: string): string | undefined =>
    typeof item[k] === 'string' ? (item[k] as string) : undefined

  const dataset = str('dataset')
  const semantic = str('semantic_name') ?? str('name') ?? str('label')
  const qualified = str('feature_id') ?? str('id')

  // A qualified id of the form "<group>.<leaf>" yields the leaf; otherwise the
  // semantic name stands in.
  const leaf =
    qualified && dataset && qualified.startsWith(`${dataset}.`)
      ? qualified.slice(dataset.length + 1)
      : semantic ?? qualified

  const id = qualified ?? (dataset && leaf ? `${dataset}.${leaf}` : (semantic ?? JSON.stringify(item)))

  const value =
    dataset && leaf
      ? { dataset, column: leaf, semantic_name: semantic ?? leaf }
      : (semantic ?? id)

  return {
    id,
    label: semantic ?? leaf ?? id,
    description: str('description'),
    group: dataset,
    value,
  }
}

interface ListEnvelope {
  data?: unknown
}

export function useEndpointOptions(path: string | null) {
  return useQuery<EndpointOption[]>({
    queryKey: ['scoping', 'options', path],
    enabled: Boolean(path),
    staleTime: 300_000,
    queryFn: async () => {
      const raw = await api.get<ListEnvelope | unknown[]>(path as string)
      const items = Array.isArray(raw) ? raw : Array.isArray(raw?.data) ? raw.data : []
      return (items as unknown[])
        .filter((i): i is Record<string, unknown> => typeof i === 'object' && i !== null)
        .map(toEndpointOption)
    },
  })
}

// ── schema: sources ──────────────────────────────────────────────────────────
//
// Resolved from the API's own OpenAPI document at runtime. This is what makes
// the filter question widen for free: when GameUniverseFilter gains a field or
// a new property, the form gains it too, with no edit here.

/** The slice of JSON Schema this UI understands. */
export interface JsonSchemaProperty {
  type?: string
  enum?: string[]
  title?: string
  description?: string
  /** Primitive types a union permits, flattened from `anyOf`. */
  anyOfTypes?: string[]
}

export interface ObjectSchema {
  name: string
  properties: { key: string; schema: JsonSchemaProperty }[]
  required: string[]
}

interface RawSchema {
  type?: string
  enum?: string[]
  title?: string
  description?: string
  anyOf?: { type?: string }[]
  properties?: Record<string, RawSchema>
  required?: string[]
}

interface OpenApiDocument {
  components?: { schemas?: Record<string, RawSchema> }
}

function toProperty(raw: RawSchema): JsonSchemaProperty {
  const anyOfTypes = (raw.anyOf ?? [])
    .map((a) => a.type)
    .filter((t): t is string => Boolean(t) && t !== 'null')
  return {
    type: raw.type,
    enum: raw.enum,
    title: raw.title,
    description: raw.description,
    anyOfTypes: anyOfTypes.length ? anyOfTypes : undefined,
  }
}

/**
 * Fetch one named object schema from the API's OpenAPI document.
 *
 * NOTE for local dev: `/openapi.json` sits outside `/api`, so the Vite dev
 * proxy (vite.config.ts, not in this task's scope) does not currently forward
 * it. Serve the built app behind the same origin as the API, or set
 * VITE_API_BASE_URL, and this resolves. Flagged to PROJECT-LEAD rather than
 * worked around by hardcoding the filter fields.
 */
export function useObjectSchema(name: string | null) {
  return useQuery<ObjectSchema>({
    queryKey: ['scoping', 'schema', name],
    enabled: Boolean(name),
    staleTime: Infinity,
    queryFn: async () => {
      const doc = await api.get<OpenApiDocument>('/openapi.json')
      const raw = doc.components?.schemas?.[name as string]
      if (!raw) throw new Error(`Schema '${name}' is not published by the API`)
      return {
        name: name as string,
        properties: Object.entries(raw.properties ?? {}).map(([key, value]) => ({
          key,
          schema: toProperty(value),
        })),
        required: raw.required ?? [],
      }
    },
  })
}

// ── Session lifecycle ────────────────────────────────────────────────────────

export const scopingKeys = {
  session: (id: string) => ['scoping', 'sessions', id] as const,
  brief: (id: string) => ['scoping', 'sessions', id, 'brief'] as const,
  review: (id: string) => ['scoping', 'sessions', id, 'review'] as const,
}

export function useStartSession() {
  return useMutation<SessionState, Error, string>({
    mutationFn: (hypothesis_text) =>
      api.post<SessionState>(`${ROOT}/sessions`, { hypothesis_text }),
  })
}

export function useSession(sessionId: string | null) {
  return useQuery<SessionState>({
    queryKey: scopingKeys.session(sessionId ?? ''),
    enabled: Boolean(sessionId),
    queryFn: () => api.get<SessionState>(`${ROOT}/sessions/${sessionId}`),
    staleTime: 0,
  })
}

/**
 * Post exactly one answer. The response IS the next state — it is written
 * straight into the session cache so no second source of truth exists.
 */
export function useAnswerSlot(sessionId: string | null) {
  const qc = useQueryClient()
  return useMutation<SessionState, Error, { slot_id: string; value: unknown }>({
    mutationFn: (body) => api.post<SessionState>(`${ROOT}/sessions/${sessionId}/answers`, body),
    onSuccess: (state) => {
      qc.setQueryData(scopingKeys.session(state.session_id), state)
      // An answer can change the config, so any rendered brief and any verdict
      // are now stale by definition.
      void qc.invalidateQueries({ queryKey: scopingKeys.brief(state.session_id) })
      void qc.invalidateQueries({ queryKey: scopingKeys.review(state.session_id) })
    },
  })
}

export function useExtract(sessionId: string | null) {
  return useMutation<ExtractResult, Error, void>({
    mutationFn: () => api.post<ExtractResult>(`${ROOT}/sessions/${sessionId}/extract`),
  })
}

/** The brief, and the hash it describes. Enabled only once nothing required is blank. */
export function useBrief(sessionId: string | null, enabled: boolean) {
  return useQuery<Brief>({
    queryKey: scopingKeys.brief(sessionId ?? ''),
    enabled: Boolean(sessionId) && enabled,
    queryFn: () => api.get<Brief>(`${ROOT}/sessions/${sessionId}/brief`),
    staleTime: 0,
    retry: false,
  })
}

export function useReview(sessionId: string | null, enabled: boolean) {
  return useQuery<Review>({
    queryKey: scopingKeys.review(sessionId ?? ''),
    enabled: Boolean(sessionId) && enabled,
    queryFn: () => api.get<Review>(`${ROOT}/sessions/${sessionId}/review`),
    staleTime: 0,
    retry: false,
  })
}

/** Approve by hash. Callers pass the hash from the most recent brief fetch. */
export function useApprove(sessionId: string | null) {
  const qc = useQueryClient()
  return useMutation<SessionState, Error, string>({
    mutationFn: (config_hash) =>
      api.post<SessionState>(`${ROOT}/sessions/${sessionId}/approve`, { config_hash }),
    onSuccess: (state) => {
      qc.setQueryData(scopingKeys.session(state.session_id), state)
    },
  })
}

export function useDispatch(sessionId: string | null) {
  const qc = useQueryClient()
  return useMutation<DispatchResult, Error, void>({
    mutationFn: () => api.post<DispatchResult>(`${ROOT}/sessions/${sessionId}/dispatch`),
    onSuccess: () => {
      void qc.invalidateQueries({ queryKey: ['experiments'] })
      if (sessionId) void qc.invalidateQueries({ queryKey: scopingKeys.session(sessionId) })
    },
  })
}
